// url-validate example: validate an HTTP(S) URL (anchored match).
// stub.rs is auto-generated by: regexped generate
include!("stub.rs");

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: url_validate <url>");
        std::process::exit(1);
    }
    let input = args[1].as_bytes();

    match url_validate::match_url(input) {
        Ok(Some(end)) => println!("Valid URL (matched {} bytes)", end),
        Ok(None)      => println!("Not a valid URL"),
        // The engine could not answer — NOT the same as "no match". See
        // docs/engines.md, "Backtracking stack overflow".
        Err(err)      => {
            eprintln!("cannot decide: {err}");
            std::process::exit(2);
        }
    }
}
